<?php
declare(strict_types=1);

require_once __DIR__ . '/../config/db.php';

function get_db(): PDO {
    static $pdo = null;
    if ($pdo === null) {
        $db = new Database();
        $pdo = $db->connect();
    }
    return $pdo;
}

function get_base_url(): string {
    $scriptName = str_replace('\\', '/', $_SERVER['SCRIPT_NAME'] ?? '');
    if (preg_match('#^(/[^/]+)#', $scriptName, $matches)) {
        $firstDir = $matches[1];
        if (strcasecmp($firstDir, '/KendatTech') === 0) {
            return $firstDir . '/';
        }
    }
    if (stripos($scriptName, '/admin/') !== false) {
        return '../';
    }
    $dir = dirname($scriptName);
    return ($dir === '/' || $dir === '.' || $dir === '\\' || $dir === '') ? '' : rtrim($dir, '/') . '/';
}

function get_settings(): array {
    static $settings = null;
    if ($settings === null) {
        try {
            $pdo = get_db();
            $stmt = $pdo->query("SELECT setting_key, setting_value FROM system_settings");
            $rows = $stmt->fetchAll();
            $settings = [];
            foreach ($rows as $row) {
                $settings[$row['setting_key']] = $row['setting_value'];
            }
        } catch (Throwable $e) {
            $settings = [];
        }
    }
    return $settings;
}

function get_setting(string $key, string $default = ''): string {
    $settings = get_settings();
    return $settings[$key] ?? $default;
}

function upload_asset_url(?string $path): string {
    if (empty($path)) return '';
    if (strpos($path, 'http://') === 0 || strpos($path, 'https://') === 0) {
        return $path;
    }
    $cleanPath = ltrim($path, '/');
    $fileOnDisk = __DIR__ . '/../uploads/' . $cleanPath;
    if (file_exists($fileOnDisk)) {
        return get_base_url() . 'uploads/' . $cleanPath;
    }
    return get_base_url() . 'uploads/' . $cleanPath;
}

require_once __DIR__ . '/upload_helper.php';

function handle_file_upload(string $fieldName, string $subfolder = 'general', bool $isPrivate = false): ?string {
    return secure_file_upload($fieldName, $subfolder, $isPrivate);
}

function handle_multiple_file_uploads(string $fieldName, string $subfolder = 'general'): array {
    if (!isset($_FILES[$fieldName]) || !is_array($_FILES[$fieldName]['name'])) {
        return [];
    }
    $paths = [];
    $count = count($_FILES[$fieldName]['name']);
    for ($i = 0; $i < $count; $i++) {
        if ($_FILES[$fieldName]['error'][$i] !== UPLOAD_ERR_OK) {
            continue;
        }
        $_FILES['_single_upload'] = [
            'name' => $_FILES[$fieldName]['name'][$i],
            'type' => $_FILES[$fieldName]['type'][$i],
            'tmp_name' => $_FILES[$fieldName]['tmp_name'][$i],
            'error' => $_FILES[$fieldName]['error'][$i],
            'size' => $_FILES[$fieldName]['size'][$i],
        ];
        $path = handle_file_upload('_single_upload', $subfolder);
        if ($path) {
            $paths[] = $path;
        }
    }
    unset($_FILES['_single_upload']);
    return $paths;
}

function slugify(string $text): string {
    $text = preg_replace('~[^\pL\d]+~u', '-', $text);
    $text = iconv('utf-8', 'us-ascii//TRANSLIT', $text);
    $text = preg_replace('~[^-\w]+~', '', $text);
    $text = trim($text, '-');
    $text = preg_replace('~-+~', '-', $text);
    $text = strtolower($text);
    return empty($text) ? 'n-a' : $text;
}

function set_flash(string $type, string $message): void {
    if (session_status() === PHP_SESSION_NONE) session_start();
    $_SESSION['flash'][$type][] = $message;
}

function get_flashes(): array {
    if (session_status() === PHP_SESSION_NONE) session_start();
    $flashes = $_SESSION['flash'] ?? [];
    unset($_SESSION['flash']);
    return $flashes;
}

